import os

# Let's check if the database file exists and what the correct path might be
# First, list files in the current directory to see what's available
print("Current directory:", os.getcwd())
print("\nFiles in current directory:")
for item in os.listdir('.'):
    print(f"  {item}")

# Let's also check for common database file extensions
print("\nLooking for database files...")
for root, dirs, files in os.walk('.'):
    for file in files:
        if file.endswith(('.db', '.sqlite', '.sqlite3', '.db3')):
            print(f"Found database: {os.path.join(root, file)}")
